const payload = msg.payload || {};
let chatId = payload.chatId;
const messageType = payload.type;
let text = (payload.content || '').trim();
const originalMsg = msg.originalMessage || {};
let userId = originalMsg.from ? originalMsg.from.id : null;
let answerCallback = null;
if (messageType === 'callback_query') {
    text = payload.data || payload.callback_data || payload.content ||
           (originalMsg.data ? originalMsg.data : '') || '';
    if (!chatId) {
        if (originalMsg.message && originalMsg.message.chat) chatId = originalMsg.message.chat.id;
        else if (originalMsg.chat) chatId = originalMsg.chat.id;
    }
    if (originalMsg.from) userId = originalMsg.from.id;
    const callbackQueryId = payload.callback_query_id || payload.id ||
        (originalMsg.id ? originalMsg.id.toString() : null);
    if (callbackQueryId) {
        answerCallback = {
            payload: { callback_query_id: callbackQueryId, text: '', show_alert: false },
            topic: 'answerCallbackQuery'
        };
    }
}
if ((messageType !== 'message' && messageType !== 'callback_query') || !text || !chatId) {
    return [null, answerCallback].filter(m => m !== null);
}
const command = text.split(' ')[0].toLowerCase();
if (!command.startsWith('/scala1_')) {
    return [null, answerCallback].filter(m => m !== null);
}
msg.telegram = { chatId, userId, command, originalText: text };
if (command === '/scala1_status') msg.topic = 'scala1_status';
else if (command === '/scala1_start') msg.topic = 'scala1_start';
else if (command === '/scala1_stop') msg.topic = 'scala1_stop';
else if (command === '/scala1_help') msg.topic = 'scala1_help';
else msg.topic = 'scala1_unknown';
return [msg, answerCallback].filter(m => m !== null);

if (msg.payload && msg.payload.callback_query_id) {
    msg.payload = {
        callback_query_id: msg.payload.callback_query_id,
        text: msg.payload.text || '',
        show_alert: msg.payload.show_alert || false
    };
    msg.topic = 'answerCallbackQuery';
    return msg;
}
return null;

const s = global.get('grundfos_scala1_state') || {};
if (!s.timestamp) {
    msg.payload = {
        chatId: msg.telegram.chatId,
        type: 'message',
        content: '⚠️ No SCALA1 data yet.\n\nCheck `grundfos-scala1-mqtt-publisher.service` and BLE range.',
        parse_mode: 'Markdown'
    };
    msg.topic = 'send';
    return msg;
}
const run = s.running === true ? '🟢 RUNNING' : (s.running === false ? '⏹ STOPPED' : '❓ Unknown');
let t = '💧 *Grundfos SCALA1 Status*\n\n';
t += `State: ${run}\n`;
if (s.pressure_bar != null) t += `Pressure: ${Number(s.pressure_bar).toFixed(2)} bar\n`;
if (s.flow_m3h != null) t += `Flow: ${Number(s.flow_m3h).toFixed(2)} m³/h\n`;
if (s.power_w != null) t += `Power: ${Math.round(Number(s.power_w))} W\n`;
if (s.mode) t += `Mode: ${s.mode}\n`;
if (s.alarm_code) t += `\n⚠️ Alarm: ${s.alarm_code}${s.alarm_text ? ' — ' + s.alarm_text : ''}\n`;
if (s.lastReportedMs) {
    const age = Math.max(0, Math.floor((Date.now() - s.lastReportedMs) / 1000));
    t += `\n🕐 Updated ${Math.floor(age / 60)}:${String(age % 60).padStart(2, '0')} ago`;
}
msg.payload = { chatId: msg.telegram.chatId, type: 'message', content: t, parse_mode: 'Markdown' };
msg.topic = 'send';
return msg;

return [
    { topic: 'water/grundfos/scala1/command', payload: { action: 'start' } },
    { payload: { chatId: msg.telegram.chatId, type: 'message', content: '💧 SCALA1 start command sent (BLE).', parse_mode: 'Markdown' }, topic: 'send' }
];

return [
    { topic: 'water/grundfos/scala1/command', payload: { action: 'stop' } },
    { payload: { chatId: msg.telegram.chatId, type: 'message', content: '⏹ SCALA1 stop command sent (BLE).', parse_mode: 'Markdown' }, topic: 'send' }
];

const helpText = `💧 *Grundfos SCALA1 Bot*\n\n` +
    `📊 \`/scala1_status\` — pressure, flow, power, alarms\n` +
    `▶️ \`/scala1_start\` — start pump (BLE, if configured)\n` +
    `⏹ \`/scala1_stop\` — stop pump (BLE, if configured)\n` +
    `❓ \`/scala1_help\` — this help\n\n` +
    `*MQTT:* water/grundfos/scala1/status\n` +
    `*Service:* grundfos-scala1-mqtt-publisher.service`;
msg.payload = {
    chatId: msg.telegram.chatId,
    type: 'message',
    content: helpText,
    parse_mode: 'Markdown'
};
msg.topic = 'send';
return msg;

msg.payload = {
    chatId: msg.telegram.chatId,
    type: 'message',
    content: `❓ Unknown SCALA1 command: ${msg.telegram.originalText}\n\nType /scala1_help for available commands.`
};
msg.topic = 'send';
return msg;
